const uint16_t* const* eggFramesForSpecies(const char* speciesName) {
  if (!speciesName) return nullptr;
  for (int i = 0; i < EGG_COUNT; i++) {
    if (strcmp(EGG_STARTER_NAMES[i], speciesName) == 0) return EGG_FRAMES[i];
  }
  return nullptr;
}
